function waysToSplit(nums) {
  const MOD = 1_000_000_007;
  const n = nums.length;
  const prefix = new Array(n + 1).fill(0);
  for (let i = 0; i < n; i++) {
    prefix[i + 1] = prefix[i] + nums[i];
  }
  const total = prefix[n];

  function firstAtLeast(target, low) {
    let high = n;
    while (low < high) {
      const middle = (low + high) >> 1;
      if (prefix[middle] >= target) {
        high = middle;
      } else {
        low = middle + 1;
      }
    }
    return low;
  }

  let count = 0;
  for (let cut = 1; cut <= n - 2; cut++) {
    const leftSum = prefix[cut];
    if (3 * leftSum > total) {
      break;
    }
    const first = firstAtLeast(2 * leftSum, cut + 1);
    const last = firstAtLeast(Math.floor((total + leftSum) / 2) + 1, cut + 1) - 1;
    if (first <= last) {
      count = (count + last - first + 1) % MOD;
    }
  }
  return count;
}

