function waysToSplit(nums) {
  const n = nums.length;
  const sum = (from, to) => nums.slice(from, to).reduce((s, v) => s + v, 0);
  let ways = 0;
  for (let i = 1; i < n - 1; i++)
    for (let j = i + 1; j < n; j++) {
      const a = sum(0, i), b = sum(i, j), c = sum(j, n);
      if (a <= b && b <= c) ways++;
    }
  return ways % 1000000007;
}

