    return [Array.from({ length: n }, () => (rand() < 0.25 ? 0 : Math.floor(rand() * (top + 1))))];
  }
  const n = 1500 + Math.floor(rand() * 501);
  const mode = Math.floor(rand() * 3);
  if (mode === 0) return [Array.from({ length: n }, () => Math.floor(rand() * 10001))];
  if (mode === 1) return [Array.from({ length: n }, () => (rand() < 0.5 ? 0 : Math.floor(rand() * 4)))];
